/usr/bin/zsh -lc "node <<'NODE'
const fs = require('node:fs');
const path = require('node:path');
const crypto = require('node:crypto');
const assert = require('node:assert/strict');
const vm = require('node:vm');
const net = require('node:net');
(async () => {
  const dir = 'verification/evidence';
  const entries = fs.readdirSync(dir).map(name => ({name, data:JSON.parse(fs.readFileSync(path.join(dir,name),'utf8'))}));
  const baseline = entries.find(entry => entry.name.endsWith('-baseline.json'));
  const preserved = ['README.md','app.cjs','verification/features.json'].map(file => {
    const hash = crypto.createHash('sha256').update(fs.readFileSync(file)).digest('hex');
    assert.equal(hash, baseline.data.hashes[file]);
    return {file, hash, unchanged:true};
  });
  const runs = entries.filter(entry => entry.data.sessions?.length);
  assert.equal(runs.length, 2);
  const checks = [];
  for (const {name,data} of runs) {
    assert.equal(data.passed, false);
    assert.deepEqual(data.features.map(f => f.name), ['sum','export']);
    assert.equal(data.features[0].response.json.result,2);
    assert.equal(data.features[1].response.status,404);
    assert(data.features.every(f => f.status === 'failed' && f.classification === 'product'));
    assert(data.doctors.every(d => d.passed));
    assert.equal(data.doctors.filter(d => d.response?.route === '/health').length,3);
    for (const session of data.sessions) {
      assert.equal(session.cleanupConfirmed,true);
      assert.equal(session.exit.code,0);
      const closed = await new Promise((resolve,reject) => {
        const socket = net.connect({host:'127.0.0.1',port:session.port});
        socket.setTimeout(1000);
        socket.once('connect', () => {socket.destroy(); resolve(false);});
        socket.once('error', error => {socket.destroy(); if(error.code === 'ECONNREFUSED') resolve(true); else reject(error);});
        socket.once('timeout', () => {socket.destroy(); reject(new Error('Closure check timed out'));});
      });
      assert(closed);
      checks.push({evidence:path.join(dir,name), port:session.port, closed, readinessPassed:true, allMappedFeaturesDriven:true});
    }
  }
  const source = fs.readFileSync('verification/run.cjs','utf8');
  const checkSource = source.slice(source.indexOf('function check('), source.indexOf('\\nasync function main()'));
  const check = vm.runInNewContext("'`(${checkSource})`);
  assert.equal(check('"'sum',{expected:12},{status:200,json:{result:12}}),true);
  assert.equal(check('sum',{expected:12},{status:200,json:{result:2}}),false);
  assert.equal(check('export',{expected:'download'},{status:404,body:'{\"error\":\"not found\"}'}),false);
  assert.equal(check('export',{expected:'download'},{status:200,contentDisposition:'attachment; filename=\"sum.csv\"',body:'result\\n12\\n'}),true);
  const runId = new Date().toISOString().replace(/[:.]/g,'-');
  const output = "'`${dir}/${runId}-validation.json`;
  const ledger = [
    {decision:'"'Replace status-only verification with documented result and readiness checks', source:baseline.name,
      alternative:'Retain HTTP-200-only check', rejectedBecause:'Original verifier exited 0 and printed sum request returned 200; both corrected real runs show result 2, expected 12', acceptedBy:checks.map(c=>c.evidence)},
    {decision:'Preserve export mapping and record a product gap', alternative:'Treat documented 404 as a successful download check or remove export',
      rejectedBecause:'Mapped expectation remains download; both real requests return 404', acceptedBy:checks.map(c=>c.evidence)},
    {decision:'Resolve app relative to verifier; bound startup, HTTP and cleanup; append unique evidence',
      acceptedBy:'Second real run from /tmp; all owned child exits confirmed; both loopback ports refuse connections; earlier evidence remains readable'}
  ];
  fs.writeFileSync(output,JSON.stringify({runId,baseline:baseline.name,preserved,checks,
    verifierHash:crypto.createHash('sha256').update(source).digest('hex'),
    controls:{sum12Passes:true,sum2Fails:true,export404Fails:true,attachmentPasses:true},
    decisions:ledger, evidenceSurvivedCleanup:entries.map(e=>e.name)},null,2)+'\\n',{flag:'wx'});
  assert(JSON.parse(fs.readFileSync(output,'utf8')).evidenceSurvivedCleanup.length === 4);
  console.log(JSON.stringify({preserved,checks,controls:'passed',evidence:output},null,2));
})().catch(error=>{console.error(error);process.exitCode=1;});
NODE"

